-- | Positions and errors returned by parsers generated by peg-hs.
--
-- A generated module exports an entry point such as
--
-- > parse :: Text -> Either ParseError Expr
--
-- Semantic actions can refer to the span of the input their alternative
-- consumed through the reserved binding @_span@, whose type is 'Span'.
module Peg.Runtime
  ( -- * Positions
    Pos (..)
  , Span (..)
    -- * Errors
  , ParseError (..)
  , Expected (..)
  , renderParseError
  ) where

import Peg.Runtime.Internal
